tool_input.command:
mkdir -p migrations/down scripts
cat > migrations/002_orders_amount_cents.sql <<'EOF'
-- Expand step of renaming orders.total_cents -> orders.amount_cents.
-- total_cents stays until a later deploy (contract step) so the previous app version keeps working.
set lock_timeout = '5s';

alter table orders add column amount_cents integer;

-- Keep both columns in sync while old and new app versions run side by side.
create function orders_sync_amount_cents() returns trigger language plpgsql as $$
begin
  if new.amount_cents is null then
    new.amount_cents := new.total_cents;
  elsif new.total_cents is null then
    new.total_cents := new.amount_cents;
  elsif tg_op = 'UPDATE' and new.amount_cents is distinct from old.amount_cents then
    new.total_cents := new.amount_cents;
  elsif tg_op = 'UPDATE' and new.total_cents is distinct from old.total_cents then
    new.amount_cents := new.total_cents;
  end if;
  return new;
end $$;

create trigger orders_sync_amount_cents before insert or update on orders
  for each row execute function orders_sync_amount_cents();
EOF
cat > migrations/down/002_orders_amount_cents.sql <<'EOF'
drop trigger orders_sync_amount_cents on orders;
drop function orders_sync_amount_cents();
alter table orders drop column amount_cents;
EOF
cat > scripts/backfill-orders-amount-cents.sql <<'EOF'
-- Run after migration 002 and repeat until it reports UPDATE 0 (batches avoid long row locks).
update orders set amount_cents = total_cents
where id in (select id from orders where amount_cents is null limit 5000);
EOF
sed -i '' 's/status, total_cents, created_at/status, amount_cents, created_at/' src/app.ts
sed -i '' 's/status, total_cents, payment_id/status, amount_cents, payment_id/' db/seed.sql
grep -rn "total_cents" . --exclude-dir=node_modules --exclude-dir=.git; (pnpm db:reset 2>&1 | tail -5)

